/bin/bash -lc "python - <<'PY'
import os, pathlib, requests, urllib.parse, json
url=os.environ['GALAXY_URL'].rstrip('/')
key=pathlib.Path(os.environ['GALAXY_API_KEY_FILE']).read_text().strip()
id='toolshed.g2.bx.psu.edu/repos/iuc/anndata_import/anndata_import/0.11.4+galaxy3'
data=requests.get(f'{url}/api/tools/{urllib.parse.quote(id, safe=\"\")}', params={'key':key,'io_details':'true'}).json()
for inp in data['inputs']:
    if inp.get('name')=='in':
        print(json.dumps(inp.get('test_param'), indent=2))
        print('case values:', [c['value'] for c in inp['cases']])
        for case in inp['cases']:
            if case['value']=='mtx':
                for sub in case['inputs']:
                    print('sub', sub['name'], sub['type'])
                    if sub['type']=='conditional':
                        print(' test', json.dumps(sub['test_param'], indent=2))
                        print(' cases', [c['value'] for c in sub['cases']])
PY"

